const icons={compass:'<circle cx="12" cy="12" r="9"/><path d="m16 8-3 5-5 3 3-5z"/>',bookmark:'<path d="M6 3h12v18l-6-4-6 4z"/>',highlight:'<path d="m14 3 7 7-10 10H4v-7zM3 22h18M11 6l7 7"/>',calendar:'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M7 2v6m10-6v6M3 11h18m-13 4h2m4 0h2"/>',search:'<circle cx="10" cy="10" r="7"/><path d="m15 15 6 6"/>',plus:'<path d="M12 4v16M4 12h16"/>',bell:'<path d="M5 16v-6a7 7 0 0 1 14 0v6l2 2H3zM9 21h6"/>',sun:'<circle cx="12" cy="12" r="4"/><path d="M12 1v3m0 16v3M1 12h3m16 0h3M4 4l2 2m12 12 2 2M4 20l2-2M18 6l2-2"/>',play:'<rect x="3" y="5" width="18" height="14" rx="3"/><path d="m10 9 5 3-5 3z"/>',news:'<rect x="4" y="3" width="16" height="18" rx="2"/><path d="M8 7h8M8 11h8M8 15h4"/>',heart:'<path d="M20 5c-3-3-6-1-8 1-2-2-5-4-8-1-4 5 2 9 8 15 6-6 12-10 8-15z"/>',comment:'<path d="M21 11a9 9 0 0 1-9 9H4l-2 2V11a9 9 0 0 1 19 0z"/>',trend:'<path d="m3 17 6-6 4 4 8-10M15 5h6v6"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 6v6l4 2"/>',logo:'<path d="m4 16 8-13 8 13-8 5zM4 16h16M12 3v18"/>'};
const svg=n=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[n]||icons.news}</svg>`;
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const load=(key,def)=>{try{return JSON.parse(localStorage.getItem('luma-'+key))??def}catch{return def}};
let saved=load('saved',[]),liked=load('liked',[]),notes=load('notes',[]),custom=load('custom',[]),rsvp=load('rsvp',[]);
const account={user:null,loading:false,ready:false,sync:null};
let communityItems=[];
const persist=(k,v)=>{if(account.user&&['saved','liked','notes','custom','rsvp'].includes(k)){if(account.ready)account.sync?.(k,v);else toast('Đang tải dữ liệu tài khoản. Vui lòng thử lại.');return}try{localStorage.setItem('luma-'+k,JSON.stringify(v))}catch{toast('Trình duyệt không cho phép lưu dữ liệu.')}};
