const seed=[
{id:'world',type:'Seminar',topic:topics[0],title:'World Models: Khi AI học cách hiểu thế giới',author:'Câu lạc bộ AI & Machine Learning',initial:'AI',date:'Tuyển chọn',duration:'58 phút',read:'8 phút đọc',views:'2.4k',likes:128,desc:'Từ mô hình ngôn ngữ đến mô hình thế giới: vì sao khả năng dự đoán, lập kế hoạch và học từ trải nghiệm là bước tiếp theo của AI?',tags:['World Models','Machine Learning','Representation Learning'],art:'world',url:'https://www.youtube.com/results?search_query=Yann+LeCun+world+models+lecture',sections:[['Từ dự đoán từ tiếp theo đến hiểu thế giới','Một mô hình ngôn ngữ học các quy luật trong chuỗi văn bản. Mô hình thế giới hướng tới việc biểu diễn trạng thái của môi trường và dự đoán điều gì sẽ xảy ra khi một tác nhân hành động. Hai cách tiếp cận này có thể bổ sung cho nhau.'],['Học những gì thực sự quan trọng','Không phải mọi chi tiết đều cần được dự đoán. Một biểu diễn hữu ích cần giữ được những yếu tố liên quan đến nhiệm vụ và bỏ qua các biến thiên không cần thiết. Đây là một câu hỏi trung tâm của representation learning.'],['Kết nối với việc lập kế hoạch','Nếu có thể dự đoán các trạng thái tương lai, tác nhân có thể so sánh những hành động khả dĩ trước khi thực hiện. Chất lượng kế hoạch vẫn phụ thuộc vào độ chính xác của mô hình và cách đánh giá mục tiêu.']],takeaway:'Một biểu diễn tốt giúp tác nhân suy nghĩ về kết quả của hành động, thay vì chỉ phản ứng với quan sát hiện tại.'},
{id:'crisis',type:'Video',topic:topics[1],title:'Khủng hoảng tài chính 2008: Một hệ thống đã đổ vỡ như thế nào?',author:'Luma Editorial',initial:'LE',date:'Tuyển chọn',duration:'24:18',read:'6 phút đọc',views:'1.8k',likes:96,desc:'Một bản đồ dễ hiểu về bong bóng bất động sản, các khoản vay dưới chuẩn và hiệu ứng domino của hệ thống tài chính toàn cầu.',tags:['Kinh tế vĩ mô','Khủng hoảng 2008','Tài chính'],art:'finance',url:'https://www.federalreservehistory.org/essays/great-recession-of-200709',sections:[['Khi rủi ro được đóng gói lại','Các khoản vay thế chấp được gom thành chứng khoán và phân phối cho nhiều nhà đầu tư. Việc chuyển giao rủi ro không khiến rủi ro biến mất; nó tạo ra mạng lưới phụ thuộc khó quan sát.'],['Đòn bẩy và hiệu ứng domino','Khi giá tài sản giảm, những tổ chức sử dụng nhiều vốn vay chịu áp lực thanh khoản. Việc bán tài sản để đáp ứng nghĩa vụ có thể làm giá tiếp tục giảm và khuếch đại khó khăn.'],['Bài học về hệ thống','Đánh giá một tổ chức riêng lẻ chưa đủ để hiểu sự an toàn của toàn bộ hệ thống. Cần nhìn cả mối liên kết, nguồn tài trợ và khả năng chịu đựng cú sốc.']],takeaway:'Rủi ro hệ thống xuất hiện trong các mối liên kết, chứ không chỉ nằm ở từng tài sản riêng lẻ.'},
{id:'learning',type:'News',topic:topics[0],title:'Học cùng AI: Câu hỏi hay quan trọng hơn câu trả lời nhanh',author:'Góc nhìn học tập',initial:'GT',date:'Tuyển chọn',duration:'',read:'5 phút đọc',views:'964',likes:72,desc:'Khi công cụ có thể giải thích mọi thứ, kỹ năng cần rèn luyện là đặt câu hỏi, kiểm chứng và tự xây dựng lại lập luận của mình.',tags:['Learning Technique','AI & Education'],art:null,url:'https://www.unesco.org/en/digital-education/artificial-intelligence',sections:[['Giữ lại công việc tư duy','Thay vì yêu cầu một đáp án hoàn chỉnh ngay từ đầu, hãy thử viết cách giải của mình rồi nhờ công cụ chỉ ra những giả định còn thiếu. Điều này tạo cơ hội để nhận diện lỗ hổng trong hiểu biết.'],['Đặt câu hỏi có thể kiểm chứng','Một câu hỏi tốt chỉ rõ điều cần giải thích, bối cảnh áp dụng và tiêu chí đánh giá. Hãy yêu cầu ví dụ phản chứng, kiểm tra nguồn và tự làm lại một bài tương tự.']],takeaway:'Dùng AI như một người đối thoại để kiểm tra cách nghĩ, và giữ quyền đánh giá cuối cùng cho chính mình.'},
{id:'beauty',type:'Video',topic:topics[2],title:'Cái đẹp có cứu rỗi thế giới? Một góc nhìn từ nghệ thuật',author:'Không gian Nhân văn',initial:'NV',date:'Tuyển chọn',duration:'14:03',read:'4 phút đọc',views:'1.2k',likes:84,desc:'Đi qua nghệ thuật và triết học để suy ngẫm về sự đồng cảm, ý nghĩa và cách con người nhìn thế giới.',tags:['Nghệ thuật','Triết học'],art:'beauty',url:'https://www.youtube.com/results?search_query=nghe+thuat+cai+dep+cuu+roi+the+gioi',sections:[['Một cách nhìn khác','Nghệ thuật không chỉ tạo ra những vật thể đẹp. Một tác phẩm còn có thể thay đổi cách người xem chú ý đến một con người, một trải nghiệm hay một vấn đề xã hội.'],['Sự đồng cảm và giới hạn','Việc tiếp xúc với góc nhìn khác có thể mở đầu cho đối thoại. Tuy nhiên, trải nghiệm thẩm mỹ không tự động chuyển thành hành động; nó cần được nối với suy nghĩ và thực hành.']],takeaway:'Giá trị của một tác phẩm đôi khi nằm ở câu hỏi nó khiến ta tiếp tục mang theo.'},
{id:'math',type:'Seminar',topic:topics[3],title:'Linear Regression: Hình học phía sau những đường thẳng',author:'Math & Learning Circle',initial:'ML',date:'Tuyển chọn',duration:'46 phút',read:'7 phút đọc',views:'786',likes:53,desc:'Hiểu bình phương tối thiểu qua phép chiếu, không gian vector và mối liên hệ với tối ưu hóa.',tags:['Linear Algebra','Statistics','Machine Learning'],art:'world',url:'https://www.youtube.com/results?search_query=linear+regression+projection+geometry',sections:[['Bình phương tối thiểu','Hồi quy tuyến tính tìm các hệ số giúp tổng bình phương sai số nhỏ nhất. Cách nhìn hình học diễn giải dự đoán như phép chiếu vector mục tiêu lên không gian sinh bởi các đặc trưng.'],['Từ hình học đến thực hành','Tương quan giữa các đặc trưng có thể làm việc ước lượng hệ số kém ổn định. Chuẩn hóa và regularization là những lựa chọn cần xem xét dựa trên mục tiêu phân tích.']],takeaway:'Cách nhìn hình học giúp kết nối một công thức thống kê với cấu trúc của dữ liệu.'}
];
let items=[...custom,...seed],state={view:'feed',type:'Tất cả',topic:'',query:'',tab:'Dành cho bạn',id:null};
if(load('theme','dark')==='light')document.body.classList.add('light');
function art(kind){if(kind==='finance')return `<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg"><defs><pattern id="grid" width="35" height="35" patternUnits="userSpaceOnUse"><path d="M35 0H0v35" fill="none" stroke="#ffffff08"/></pattern></defs><rect width="700" height="260" fill="#252321"/><rect width="700" height="260" fill="url(#grid)"/><text x="35" y="49" fill="#b8a99a" font-family="sans-serif" font-size="10" letter-spacing="3">THE ANATOMY OF A CRISIS</text><text x="31" y="149" fill="#d5c4b3" font-family="Georgia,serif" font-size="94">2008</text><path d="m285 80 35 13 30-26 27 35 30-8 35 32 25-8 27 38 28-7 23 34 36-9 31 37 40 12" fill="none" stroke="#db9d88" stroke-width="3"/><path d="m285 80 35 13 30-26 27 35 30-8 35 32 25-8 27 38 28-7 23 34 36-9 31 37 40 12V260H285Z" fill="#ce8e7510"/><text x="37" y="190" fill="#a19387" font-family="sans-serif" font-size="13">When everything is connected.</text><circle cx="637" cy="223" r="4" fill="#f5afa1"/></svg>`;
if(kind==='beauty')return `<svg viewBox="0 0 700 260"><defs><radialGradient id="b"><stop stop-color="#68665e"/><stop offset="1" stop-color="#272d2b"/></radialGradient></defs><rect width="700" height="260" fill="#262b2c"/><circle cx="520" cy="200" r="180" fill="url(#b)"/><path d="M490 25c-75 20-88 78-61 122l-20 34 29 6c0 48 40 65 91 52l28-53c31-13 51-66 23-105-21-40-56-65-90-56" fill="#b6aa91" opacity=".45"/><path d="m460 102 69-9-37 37 22 42-37 8m0-45-18 14" fill="none" stroke="#d8c9ae" opacity=".3" stroke-width="3"/><text x="35" y="50" fill="#b7b0a4" font-size="10" letter-spacing="3">ART, MEANING & THE HUMAN CONDITION</text><text x="35" y="115" fill="#e2d9c9" font-family="Georgia,serif" font-size="37">Can beauty</text><text x="35" y="163" fill="#e2d9c9" font-family="Georgia,serif" font-size="37">save the world?</text></svg>`;
return `<svg viewBox="0 0 700 260"><defs><pattern id="dots" width="18" height="18" patternUnits="userSpaceOnUse"><circle cx="1" cy="1" r=".7" fill="#c8d3ad22"/></pattern><radialGradient id="glow"><stop stop-color="#667953" stop-opacity=".25"/><stop offset="1" stop-color="#151e19" stop-opacity="0"/></radialGradient></defs><rect width="700" height="260" fill="#17201b"/><rect width="700" height="260" fill="url(#dots)"/><ellipse cx="375" cy="140" rx="270" ry="140" fill="url(#glow)"/><text x="26" y="31" fill="#8b9b82" font-family="monospace" font-size="9" letter-spacing="2">LEARNING BEYOND LANGUAGE</text><g stroke="#8b9b6f" stroke-width="1" fill="none"><path d="M115 138h94m92 0h96m92 0h82"/><path d="m201 134 8 4-8 4m188-8 8 4-8 4m174-8 8 4-8 4"/><ellipse cx="258" cy="137" rx="48" ry="48"/><ellipse cx="258" cy="137" rx="23" ry="48"/><ellipse cx="258" cy="137" rx="48" ry="18"/><path d="M210 137h96m-48-48v96"/><path d="m438 92 42 24v49l-42 25-42-25v-49zM396 116l42 24 42-24m-42 24v50"/><rect x="570" y="112" width="73" height="50" rx="6"/><rect x="45" y="112" width="70" height="50" rx="6"/></g><g fill="#d6ddbc" font-family="monospace" text-anchor="middle"><text x="80" y="142" font-size="12">x(t)</text><text x="606" y="142" font-size="12">x(t+1)</text><text x="258" y="216" font-size="10">OBSERVE</text><text x="438" y="216" font-size="10">UNDERSTAND</text><text x="606" y="216" font-size="10">PREDICT</text></g><circle cx="258" cy="89" r="3" fill="#d1dcb2"/><circle cx="438" cy="140" r="3" fill="#d1dcb2"/></svg>`}
function shell(content,rail){return `<aside class="sidebar"><a class="brand" href="#" aria-label="Luma trang chủ">${svg('logo')}luma<i>BETA</i></a>${[['feed','compass','Khám phá'],['saved','bookmark','Thư viện của tôi'],['notes','highlight','Highlights & Notes'],['events','calendar','Lịch seminar']].map(([v,i,t])=>`<button class="nav ${state.view===v?'active':''}" data-view="${v}">${svg(i)}${t}</button>`).join('')}<div class="section-label">CHỦ ĐỀ CỦA BẠN</div>${topics.map((t,i)=>`<button class="topic-nav" data-topic="${t}"><span class="dot" style="background:${['#b2c7a4','#d3b88d','#b8a5cf','#a4b9ce'][i]}"></span>${t}</button>`).join('')}<div class="sidebar-bottom"><button class="nav" id="theme">${svg('sun')}<span>${document.body.classList.contains('light')?'Giao diện sáng':'Giao diện tối'}</span></button><div class="profile"><span class="avatar">N</span><div><strong>Không gian của bạn</strong><small>Luôn giữ sự tò mò.</small></div></div></div></aside><div class="shell"><a href="#" class="mobile-brand">◈ luma</a><header class="topbar"><div class="search">${svg('search')}<input id="search" aria-label="Tìm kiếm nội dung" placeholder="Tìm một ý tưởng, chủ đề hoặc người chia sẻ..." value="${esc(state.query)}"><kbd>/</kbd></div><div class="topright"><button class="primary" id="add">${svg('plus')}Thêm nội dung</button></div></header><div class="layout"><main>${content}</main><aside class="right-rail ${state.view==='reader'?'reader-rail':''}">${rail}</aside></div></div>`}
function card(x){const s=saved.includes(x.id);return `<article class="feed-card"><div class="card-top"><span class="type ${x.type}">${svg(x.type==='Seminar'?'calendar':x.type==='Video'?'play':'news')}${x.type==='Video'?'VIDEO SUMMARY':x.type.toUpperCase()}</span><span>·</span><span>${esc(x.topic)}</span><span class="spacer"></span><span>${esc(x.date)}</span></div><button class="card-title" data-open="${x.id}">${esc(x.title)}</button><div class="byline"><span class="mini-avatar">${esc(x.initial)}</span>${esc(x.author)}<span aria-hidden="true">·</span><span>· ${esc(x.read)}</span></div><p class="description">${esc(x.desc)}</p>${x.art?`<div class="art" role="button" tabindex="0" data-open="${x.id}" aria-label="Đọc ${esc(x.title)}">${art(x.art)}<span class="play">▶ &nbsp; Khám phá nội dung</span><span class="duration">${esc(x.duration)}</span></div>`:''}<div class="tags">${x.tags.map(t=>`<button class="tag" data-search="${esc(t)}">${esc(t)}</button>`).join('')}</div><div class="card-footer"><button class="action ${liked.includes(x.id)?'selected':''}" data-like="${x.id}" aria-label="Yêu thích">${svg('heart')}${x.likes+(liked.includes(x.id)?1:0)}</button><button class="action" data-open="${x.id}">${svg('highlight')}${notes.filter(n=>n.id===x.id).length||'Ghi chú'}</button><button class="action ${s?'selected':''}" data-save="${x.id}" aria-label="${s?'Bỏ lưu':'Lưu'} ${esc(x.title)}">${svg('bookmark')}${s?'Đã lưu':'Lưu'}</button><button class="read" data-open="${x.id}">Đọc tóm tắt</button></div></article>`}
function rightRail(){return `<div class="edition"><span>YOUR DAILY DOSE OF CURIOSITY</span><span>✧</span></div><section class="feature"><div class="eyebrow">BỘ SƯU TẬP NỔI BẬT</div><h3>Hiểu AI.<br>Hiểu tương lai.</h3><p>Những ý tưởng lớn, từ nền tảng đến biên giới mới của trí tuệ nhân tạo.</p><button data-topic="${topics[0]}">Khám phá bộ sưu tập</button></section><section class="rail-section"><div class="rail-head"><h3>Seminar sắp tới</h3><button data-view="events">Xem lịch</button></div>${eventsMarkup(true)}</section><section class="rail-section"><div class="rail-head"><h3>Đi theo sự tò mò</h3></div>${topics.map((t,i)=>`<button class="topic-row" data-topic="${t}" style="width:100%"><span class="dot" style="background:${['#b2c7a4','#d3b88d','#b8a5cf','#a4b9ce'][i]}"></span><span>${t}</span><small>${items.filter(x=>x.topic===t).length}</small></button>`).join('')}</section><div class="newsletter"><h3>Ít nhiễu hơn. Nhiều góc nhìn hơn.</h3><p>Mỗi ý tưởng đáng nhớ đều xứng đáng có một chỗ trong thư viện của bạn.</p><button data-view="saved">Mở thư viện của tôi</button></div><div class="rail-foot">Luma · A space for curious minds.<br>Bản mẫu tương tác · Nội dung minh họa</div>`}
const events=[{id:'e1',day:'28',month:'TH11',title:'Reading group: World Models',time:'19:30 – 21:00 · Online',topic:topics[0]},{id:'e2',day:'30',month:'TH11',title:'Tư duy xác suất trong đời sống',time:'20:00 – 21:30 · Online',topic:topics[3]}];
function eventsMarkup(compact=false){return events.map(e=>`<div class="event"><div class="date-box"><small>${e.month}</small>${e.day}</div><div><strong>${e.title}</strong><p>${e.time}</p>${!compact?`<p>${e.topic} · Lịch minh họa, không phải sự kiện thực tế</p><button class="chip ${rsvp.includes(e.id)?'active':''}" data-rsvp="${e.id}">${rsvp.includes(e.id)?'Đã đặt nhắc lịch':'Lưu nhắc lịch (.ics)'}</button>`:''}</div></div>`).join('')}
function heading(title,desc){return `<div class="heading"><span class="eyebrow">A SPACE FOR CURIOUS MINDS</span><h1>${title}</h1><p>${desc}</p></div>`}
function noteCard(n,withTitle=false){const x=items.find(x=>x.id===n.id);return `<div class="note-item">${withTitle&&x?`<button class="related" data-open="${x.id}"><strong>${esc(x.title)}</strong></button>`:''}${n.quote?`<blockquote>${esc(n.quote)}</blockquote>`:''}${n.text?`<p>${esc(n.text)}</p>`:''}<button data-delete="${n.key}">Xóa ghi chú</button></div>`}
function render(){let content='',rail=rightRail();if(state.view==='reader'){const x=items.find(x=>x.id===state.id);if(!x){go('feed');return}const local=notes.filter(n=>n.id===x.id);content=`<article class="reader"><div class="reader-header"><button class="back" data-view="feed">‹ &nbsp; Quay lại khám phá</button><span class="tag">${x.type} · ${x.read}</span></div><span class="eyebrow">${esc(x.topic)}</span><h1>${esc(x.title)}</h1><div class="byline"><span class="mini-avatar">${esc(x.initial)}</span>${esc(x.author)}</div><div class="reader-toolbar"><button data-save="${x.id}">${saved.includes(x.id)?'✓ Đã lưu vào thư viện':'♡ Lưu vào thư viện'}</button><a href="${esc(x.url)}" target="_blank" rel="noopener noreferrer">${x.url.includes('results?')?'Tìm video nguồn':'Mở nguồn tham khảo'}</a><button id="copy">Sao chép liên kết</button></div>${x.art?`<div class="art">${art(x.art)}<span class="duration">${esc(x.duration)}</span></div>`:''}<div class="summary"><span class="eyebrow">Ý TƯỞNG CỐT LÕI</span><p>${esc(x.takeaway||x.desc)}</p></div><p class="hint">Bôi đen một đoạn văn bên dưới để highlight và lưu ghi chú.</p><div id="reading-content"><h2>Tổng quan</h2><p data-par="intro">${esc(x.desc)}</p>${x.sections.map(([title,text],i)=>`<section id="section-${i}"><h2>${esc(title)}</h2><p data-par="${i}">${esc(text)}</p></section>`).join('')}</div><p class="hint">${x.id.startsWith('custom')?'Nội dung do bạn thêm.':'Bản tóm tắt minh họa do Luma biên soạn theo chủ đề; không phải bản chép lời hay tóm tắt đã đối chiếu một video cụ thể.'}</p></article>`;const related=items.filter(a=>a.id!==x.id).sort((a,b)=>(b.topic===x.topic)-(a.topic===x.topic)).slice(0,3);rail=`<section class="rail-section"><div class="rail-head"><h3>Trong nội dung này</h3></div><a class="related" href="#reading-content">Tổng quan</a>${x.sections.map(([t],i)=>`<a class="related" href="#section-${i}">${esc(t)}</a>`).join('')}</section><section class="rail-section"><div class="rail-head"><h3>Highlights & Notes <span class="tag">${local.length}</span></h3></div>${local.length?local.map(n=>noteCard(n)).join(''):'<p class="hint">Giữ lại những điều khiến bạn suy nghĩ.</p>'}<textarea class="note-compose" id="free-note" aria-label="Ghi chú cá nhân" placeholder="Viết suy nghĩ của bạn..."></textarea><button class="primary" id="save-note" style="margin-top:8px">Lưu ghi chú</button></section><section class="rail-section"><div class="rail-head"><h3>Kết nối ý tưởng</h3></div>${related.map(a=>`<button class="related" data-open="${a.id}"><small>${a.type} · ${esc(a.topic)}</small><strong>${esc(a.title)}</strong></button>`).join('')}</section>`;
}else if(state.view==='events'){content=heading('Hẹn một buổi, mở một góc nhìn.','Lịch seminar minh họa · Thời gian Asia/Bangkok (UTC+7).')+eventsMarkup();}else if(state.view==='notes'){content=heading('Những điều đọng lại.','Highlights và suy nghĩ của bạn, kết nối với từng nội dung.');const ns=notes.filter(n=>(n.quote+' '+n.text+' '+(items.find(x=>x.id===n.id)?.title||'')).toLocaleLowerCase().includes(state.query.toLocaleLowerCase()));content+=ns.length?ns.map(n=>noteCard(n,true)).join(''):'<div class="empty">Chưa có ghi chú phù hợp.<br>Mở một nội dung, bôi đen câu bạn thích và lưu lại.</div>';}else{let list=items.filter(x=>(state.view!=='saved'||saved.includes(x.id))&&(state.type==='Tất cả'||x.type===state.type)&&(!state.topic||x.topic===state.topic)&&[x.title,x.desc,x.topic,...x.tags].join(' ').toLocaleLowerCase().includes(state.query.toLocaleLowerCase()));if(state.tab==='Đang nổi bật')list.sort((a,b)=>b.likes-a.likes);if(state.tab==='Mới nhất')list.sort((a,b)=>(b.timestamp||0)-(a.timestamp||0));content=heading(state.view==='saved'?'Một thư viện, nhiều góc nhìn.':'Khám phá. Kết nối. Hiểu sâu hơn.',state.view==='saved'?'Những nội dung bạn muốn quay lại.':'Seminar, video và tin tức — những ý tưởng đáng để dành thời gian.')+`<div class="tabs">${['Dành cho bạn','Đang nổi bật','Mới nhất'].map(t=>`<button class="tab ${state.tab===t?'active':''}" data-tab="${t}">${t==='Đang nổi bật'?svg('trend'):''}${t}</button>`).join('')}${state.topic?`<button class="tab" id="clear-topic">✕ Chủ đề</button>`:''}</div><div class="filters">${['Tất cả','Seminar','Video','News'].map(t=>`<button class="chip ${state.type===t?'active':''}" data-type="${t}">${t==='Video'?'Video Summary':t}</button>`).join('')}${state.topic?`<span class="tag">${esc(state.topic)}</span>`:''}</div>${list.length?list.map(card).join(''):'<div class="empty">Chưa có nội dung phù hợp.<br>Thử từ khóa khác hoặc lưu một nội dung vào thư viện.</div>'}`;}document.querySelector('#app').innerHTML=shell(content,rail);bind();if(state.view==='reader')restoreHighlights();}
function go(view){state.view=view;state.query='';state.id=null;state.topic='';state.type='Tất cả';if(location.hash.startsWith('#read/'))history.replaceState(null,'',location.pathname);render();window.scrollTo(0,0)}
function openItem(id){state.view='reader';state.id=id;state.query='';history.replaceState(null,'','#read/'+encodeURIComponent(id));render();window.scrollTo(0,0)}
let toastTimer;function toast(s){const e=document.querySelector('#toast');e.textContent=s;e.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>e.classList.remove('show'),2700)}
function bind(){document.querySelectorAll('[data-view]').forEach(e=>e.onclick=()=>go(e.dataset.view));document.querySelectorAll('[data-open]').forEach(e=>{e.onclick=()=>openItem(e.dataset.open);if(e.tagName==='DIV')e.onkeydown=ev=>{if(ev.key==='Enter'||ev.key===' '){ev.preventDefault();openItem(e.dataset.open)}}});document.querySelectorAll('[data-save]').forEach(e=>e.onclick=()=>{const id=e.dataset.save;saved=saved.includes(id)?saved.filter(a=>a!==id):[...saved,id];persist('saved',saved);render();toast(saved.includes(id)?'Đã lưu vào thư viện':'Đã bỏ lưu')});document.querySelectorAll('[data-like]').forEach(e=>e.onclick=()=>{const id=e.dataset.like;liked=liked.includes(id)?liked.filter(a=>a!==id):[...liked,id];persist('liked',liked);render()});document.querySelectorAll('[data-type]').forEach(e=>e.onclick=()=>{state.type=e.dataset.type;render()});document.querySelectorAll('[data-tab]').forEach(e=>e.onclick=()=>{state.tab=e.dataset.tab;render()});document.querySelectorAll('[data-topic]').forEach(e=>e.onclick=()=>{state.topic=e.dataset.topic;state.view='feed';state.type='Tất cả';state.query='';render();window.scrollTo(0,0)});document.querySelectorAll('[data-search]').forEach(e=>e.onclick=()=>{state.query=e.dataset.search;render()});document.querySelector('#clear-topic')?.addEventListener('click',()=>{state.topic='';render()});document.querySelectorAll('[data-delete]').forEach(e=>e.onclick=()=>{notes=notes.filter(n=>n.key!==e.dataset.delete);persist('notes',notes);render()});document.querySelector('#search').oninput=e=>{state.query=e.target.value;const pos=e.target.selectionStart;if(state.view==='reader'||state.view==='events')state.view='feed';render();const input=document.querySelector('#search');input.focus();input.setSelectionRange(pos,pos)};document.querySelector('#theme').onclick=()=>{document.body.classList.toggle('light');persist('theme',document.body.classList.contains('light')?'light':'dark');render()};document.querySelector('#add').onclick=()=>document.querySelector('dialog').showModal();document.querySelector('#copy')?.addEventListener('click',async()=>{try{await navigator.clipboard.writeText(location.href);toast('Đã sao chép liên kết')}catch{toast('Không thể truy cập clipboard. Hãy sao chép URL trên thanh địa chỉ.')}});document.querySelector('#save-note')?.addEventListener('click',()=>{const text=document.querySelector('#free-note').value.trim();if(!text){toast('Viết ghi chú trước khi lưu.');return}notes.push({key:crypto.randomUUID(),id:state.id,text,quote:''});persist('notes',notes);render();toast('Đã lưu ghi chú')});document.querySelectorAll('[data-rsvp]').forEach(e=>e.onclick=()=>{const event=events.find(x=>x.id===e.dataset.rsvp);const day=event.day;const data=`BEGIN:VCALENDAR\r\nVERSION:2.0\r\nPRODID:-//Luma//Seminar//VI\r\nBEGIN:VEVENT\r\nUID:${event.id}@luma.local\r\nDTSTAMP:20261123T000000Z\r\nDTSTART:202611${day}T${event.id==='e1'?'123000':'130000'}Z\r\nDTEND:202611${day}T140000Z\r\nSUMMARY:[Minh họa] ${event.title}\r\nDESCRIPTION:Lịch minh họa từ Luma. Không phải sự kiện thực tế.\r\nEND:VEVENT\r\nEND:VCALENDAR`;const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([data],{type:'text/calendar;charset=utf-8'}));a.download='luma-seminar.ics';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);if(!rsvp.includes(event.id))rsvp.push(event.id);persist('rsvp',rsvp);render();toast('Đã tải lịch minh họa (.ics)')});}
function restoreHighlights(){const local=notes.filter(n=>n.id===state.id&&n.quote&&n.par!==undefined);for(const n of local){const p=document.querySelector(`[data-par="${n.par}"]`);if(!p)continue;const walker=document.createTreeWalker(p,NodeFilter.SHOW_TEXT);let node;while(node=walker.nextNode()){const i=node.textContent.indexOf(n.quote);if(i<0||node.parentElement.closest('mark'))continue;const range=document.createRange();range.setStart(node,i);range.setEnd(node,i+n.quote.length);const m=document.createElement('mark');range.surroundContents(m);break}}}
let selected=null;document.addEventListener('mouseup',e=>{if(e.target.closest('.selection-tools'))return;document.querySelector('.selection-tools')?.remove();if(state.view!=='reader')return;const sel=window.getSelection();if(!sel||sel.isCollapsed||!sel.toString().trim())return;const range=sel.getRangeAt(0);const start=range.startContainer.parentElement.closest('[data-par]'),end=range.endContainer.parentElement.closest('[data-par]');if(!start||start!==end)return;selected={quote:sel.toString(),par:start.dataset.par};const box=range.getBoundingClientRect();const panel=document.createElement('div');panel.className='selection-tools';panel.style.left=Math.max(10,Math.min(box.left,innerWidth-320))+'px';panel.style.top=Math.max(10,Math.min(box.bottom+9,innerHeight-130))+'px';panel.innerHTML='<input aria-label="Ghi chú cho highlight" placeholder="Thêm một suy nghĩ (không bắt buộc)"><button>Lưu highlight</button>';panel.querySelector('button').onclick=()=>{notes.push({key:crypto.randomUUID(),id:state.id,...selected,text:panel.querySelector('input').value.trim()});persist('notes',notes);panel.remove();window.getSelection().removeAllRanges();render();toast('Đã lưu highlight')};document.body.append(panel)});
document.querySelector('#publish-form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target);const url=new URL(f.get('url'));if(!['https:','http:'].includes(url.protocol)){toast('Đường dẫn cần bắt đầu bằng https:// hoặc http://');return}const x={id:'custom-'+crypto.randomUUID(),type:f.get('type'),topic:f.get('topic'),title:f.get('title').trim(),desc:f.get('desc').trim(),url:url.href,author:'Bạn',initial:'N',date:'Vừa thêm',read:'2 phút đọc',views:'0',likes:0,duration:'',art:null,tags:[f.get('topic')],sections:[],takeaway:f.get('desc').trim()};if(!x.title||!x.desc)return;custom.unshift(x);persist('custom',custom);items=[...custom,...seed];e.target.reset();document.querySelector('dialog').close();go('feed');toast('Đã thêm nội dung của bạn')};
document.addEventListener('keydown',e=>{if(e.key==='/'&&!['INPUT','TEXTAREA','SELECT'].includes(document.activeElement.tagName)&&!document.querySelector('dialog').open){e.preventDefault();document.querySelector('#search').focus()}if(e.key==='Escape')document.querySelector('.selection-tools')?.remove()});
document.addEventListener('click',e=>{if(e.target.closest('.brand,.mobile-brand')){e.preventDefault();go('feed')}});window.addEventListener('hashchange',()=>{if(location.hash.startsWith('#read/')){const id=decodeURIComponent(location.hash.slice(6));if(items.some(x=>x.id===id))openItem(id)}});if(location.hash.startsWith('#read/')){state.view='reader';state.id=decodeURIComponent(location.hash.slice(6))}render();
